// frontend/src/api/scan.js

/**
 * POST /scan 엔드포인트를 호출하여 스캔 결과를 가져옵니다.
 * @param {string} target IP 또는 도메인
 */
export async function loadScanData(target) {
  const res = await fetch('http://127.0.0.1:8000/scan', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ target })
  });
  const data = await res.json();
  if (!res.ok) {
    // backend 에서 던진 detail 메시지를 에러로 표출
    throw new Error(data.detail || '스캔 중 오류가 발생했습니다.');
  }
  return data;
}
